from questions._util import IX, q

PSA = "https://labs.iximiuz.com/challenges/roll-out-pod-security-standards-across-three-namespaces-1be633bd"
PROBE = "https://labs.iximiuz.com/challenges/debug-pod-stuck-at-01-ready-due-to-a-readiness-probe-3e64d4a8"
INGRESS = "https://labs.iximiuz.com/challenges/troubleshoot-ingress-returns-503-service-unavailable-8cadc570"
GW = "https://labs.iximiuz.com/challenges/migrate-production-ingress-to-gateway-api-9c9c8339"

QUESTIONS = [
    q("k8s-pods", "medium", "A Pod is the thing you debug, but a Deployment is what you edit. Why?", "The Deployment owns a ReplicaSet that owns the Pods. A replaced Pod gets a new name and a new IP.", "Pods are durable and keep their IP across a reschedule.", "A Deployment is only a label.", "ReplicaSets do not create Pods.", "Treat the Pod as disposable. Put the desired state in the owner."),
    q("k8s-pods", "medium", "Two containers in one Pod share:", "The network namespace and can use localhost to reach each other. They do not share a filesystem unless a volume is mounted in both.", "A process list only. Localhost does not cross containers.", "Nothing. Sidecars are a Service.", "The image layers, so a write in one appears in the other automatically.", "localhost works. The disk does not, unless you mount the same volume."),
    q("k8s-pods", "easy", "What does a restartPolicy of Always on a Pod mean when the process exits?", "The kubelet starts the container again. It does not mean the Pod object is recreated by a controller.", "The node is rebooted.", "The Service IP changes.", "The Pod is deleted from etcd immediately and never returns.", "Restart is a kubelet action on the same Pod. A Deployment replace is a different event."),
    q("k8s-pods", "hard", "An init container has not finished. What is true of the app container?", "It has not started. Init containers run to completion first, in order.", "It is already serving and the init container is optional logging.", "Init containers run beside the app.", "They only run after the readiness probe passes.", "A stuck init container is why the app never appears. Read its logs before you blame the app image."),
    q("k8s-workloads", "medium", "You need one pod on every node, including nodes that join later. Which object?", "A DaemonSet.", "A Deployment with replicas equal to today's node count.", "A Job.", "A StatefulSet. That gives stable identity, not 'one per node'.", "DaemonSets track the node list. A fixed replica count will not."),
    q("k8s-workloads", "medium", "A database needs a stable name and its own disk per ordinal. What fits?", "A StatefulSet with a volumeClaimTemplate.", "A Deployment with one shared PVC in ReadWriteOnce across every replica.", "A CronJob.", "A bare Pod with no owner.", "Ordinals and per-pod PVCs are the StatefulSet feature. A Deployment pod name changes."),
    q("k8s-workloads", "easy", "A Job is done when:", "The required number of pods exit successfully. A Deployment would restart that exit.", "The pod stays Running.", "It has been scheduled once, regardless of the exit code.", "A Service selects it.", "Jobs want completion. Deployments want a process that stays up."),
    q("k8s-workloads", "hard", "You changed a Deployment's pod template and the old pods are still there. What are you waiting on?", "The rollout. maxUnavailable and maxSurge, plus readiness, decide how fast old ReplicaSets shrink.", "A node reboot, which is the only way a template change applies.", "etcd compaction.", "The pods adopt the new template in place. They do not. A new pod is created.", "Watch the new ReplicaSet. A failing probe will pin the rollout and leave the old pods serving."),
    q("k8s-config", "medium", "You mounted a ConfigMap on /etc/app and the image's files in that directory vanished. Why?", "A volume mount hides the directory underneath it. Mount a single file with subPath, or mount on an empty path.", "ConfigMaps delete image files in the registry.", "The kubelet cannot project files.", "subPath is what hides the directory. It is the opposite.", "The mount is a directory. The files baked into the image at that path are not merged in.", IX, "https://labs.iximiuz.com/challenges/inject-configmap-file-without-overwriting-existing-directory-23bcc10e"),
    q("k8s-config", "easy", "A ConfigMap is for:", "Configuration that is not a credential. It is world-readable to anyone who can get it in the namespace.", "Passwords, because the name says config.", "Node bootstrap only.", "Container images.", "If it is secret, use a Secret or an external store. ConfigMaps end up in manifests and logs."),
    q("k8s-config", "medium", "You edited a ConfigMap and the pod still has the old env var. Why?", "Env vars from a ConfigMap are copied at pod start. A mounted file can update. The env var will not.", "Env vars refresh every second.", "ConfigMaps are immutable and the edit did not save. They are mutable unless you marked them immutable.", "The kubelet restarts the pod on every ConfigMap write.", "Roll the pod to pick up env. Do not expect a running process to see a new env block."),
    q("k8s-config", "hard", "An immutable ConfigMap will not let you change a key. What do you do for a new revision?", "Create a new ConfigMap and point the pod template at it. The rollout then replaces pods.", "kubectl edit --force, which rewrites immutable objects in place.", "Delete the key from etcd with a curl to the node.", "Immutable only applies to Secrets.", "Immutability makes the revision explicit. The name or the pod spec has to change."),
    q("k8s-secrets", "medium", "A Kubernetes Secret is base64 in the API. What does that not give you?", "Encryption or access control. Base64 is encoding. RBAC and encryption at rest are the controls.", "A way to store bytes.", "A volume or an env var projection.", "A namespace-scoped object.", "Anyone who can get secrets can read them. Do not treat the manifest as safe to paste into a ticket."),
    q("k8s-secrets", "medium", "The pod is CreateContainerConfigError and the message names a secret. What is wrong?", "The secret, or the key inside it, is not in the namespace the pod is in.", "The image is too large.", "The node is NotReady. That is a different status.", "The Service has no endpoints.", "Config errors happen before the process starts. Read the event. It names the missing object."),
    q("k8s-secrets", "easy", "Where should a production database password live if you can choose?", "A secret manager, projected in at runtime. Not in the image and not in git.", "In the Deployment env as a literal.", "In a ConfigMap, because it is easier to diff.", "In the container args, which are hidden.", "Git and images leak. The cluster secret is a step up and still needs RBAC and encryption at rest."),
    q("k8s-secrets", "hard", "You rotated a TLS secret and the ingress still serves the old cert. What is likely stale?", "The ingress controller has not reloaded, or you edited a different secret than the one the listener uses.", "Secrets cannot be rotated.", "TLS secrets are copied into the image at pull time.", "kube-proxy serves the certificate.", "Confirm the secret name on the Ingress or Gateway, then the controller's reload. Creating a second secret does nothing until it is referenced."),
    q("k8s-services", "medium", "A Service is ClusterIP and pods are Running and Ready. From another pod, what do you call?", "The Service name and port. The Service IP is stable. Pod IPs are not.", "The pod IP you saw in kubectl get pods. It is the contract.", "The node IP and a random port.", "The container id.", "DNS for the Service is the API. Pod IPs change on every recreate."),
    q("k8s-services", "medium", "Endpoints are empty and the Service exists. What is the usual selector bug?", "The selector does not match the pod labels, or no pod is Ready.", "Services do not use selectors.", "Endpoints fill in even when no pod matches, with the node IP.", "Readiness does not affect endpoints.", "kubectl get endpoints. If it is empty, either nothing matches or nothing is ready."),
    q("k8s-services", "easy", "What is a headless Service for?", "DNS records for the pod IPs, with no virtual IP. Stateful sets use this.", "A Service that drops all traffic.", "LoadBalancer without a cloud.", "A Service in kube-system only.", "clusterIP: None means the DNS name returns the pods, not one VIP."),
    q("k8s-services", "hard", "NodePort opened a port on every node. Who still has to be able to reach that node port?", "The client network, and any cloud security group in front of the node. Kubernetes allocating the port does not punch the cloud firewall.", "Nobody. NodePort is loopback only.", "Only pods in the same namespace. NodePort is not reachable from outside.", "The API server, which proxies all NodePort traffic. It does not.", "NodePort allocates. The network in front of the node still has to allow it."),
    q("k8s-ingress", "medium", "An Ingress returns 503 and the Service has no ready endpoints. Where is the fault?", "In the pods or their readiness, not in the Ingress path rule. The proxy has nobody to send to.", "The Ingress class is always the bug when the status is 503.", "503 means the certificate expired.", "The client DNS is wrong, which would be a timeout or a different site, not a 503 from your ingress.", "Fix readiness and the selector first.", IX, INGRESS),
    q("k8s-ingress", "medium", "You are moving a host and two paths from an Ingress to the Gateway API. What replaces the path rules?", "An HTTPRoute attached to a Gateway, with the same host and backend Services.", "A second Ingress with a different class, which is still Ingress.", "A DaemonSet.", "A NetworkPolicy.", "Gateway is the listener. HTTPRoute is the routing. Keep the backends pointed at the same Services until you cut traffic.", IX, GW),
    q("k8s-ingress", "easy", "Ingress is layer 7. A Service of type LoadBalancer is typically:", "A cloud load balancer aimed at the Service's ports, without HTTP path routing unless the cloud controller adds it.", "Always an HTTP router with path rules.", "A replacement for DNS inside the cluster.", "Only reachable from the same pod.", "Use Ingress or Gateway when the URL matters. Use a load balancer Service when you want a stable external address for a port."),
    q("k8s-ingress", "hard", "Two Ingresses claim the same host and path on the same class. What happens?", "The controller's conflict behavior. One of them wins or the config is rejected. Do not assume they merge.", "Kubernetes merges them in etcd automatically.", "Both are served at random per request with no warning.", "Ingress objects cannot share a host, and the API always rejects the second create. Not every API version does.", "Read the controller's logs. The API server often accepts both objects."),
    q("k8s-probes", "medium", "A readiness exec probe fails every time. The same command succeeds when you run it in the container, and the events say the probe timed out. Which default is too small?", "timeoutSeconds, which defaults to 1. The command is killed if it runs longer.", "periodSeconds, which defaults to 1.", "successThreshold, which defaults to 10 for readiness.", "failureThreshold, which stops the command at 1 second.", "timeoutSeconds bounds one attempt. periodSeconds is only the gap between attempts. Raise the timeout and recreate the pod. Probe fields are immutable.", IX, PROBE),
    q("k8s-probes", "medium", "Liveness and readiness fail the same way and you only add a liveness probe. What extra outage did you create?", "The kubelet restarts the container whenever the check fails, including during a slow dependency. Readiness would only have removed it from the Service.", "Liveness never restarts a container.", "Readiness deletes the Deployment.", "They are the same probe with two names.", "Use readiness to leave the pool. Use liveness only for a process that is truly stuck, and give a slow start a startupProbe."),
    q("k8s-probes", "hard", "You fixed the probe in the YAML and kubectl apply says the probe field is immutable. What now?", "Recreate the pod. A running pod does not accept probe edits.", "The apply already worked and the message is a warning.", "Annotate the pod with kubectl.kubernetes.io/restartedAt. That edits the probe in place.", "Delete the Service.", "The error names the field. Replace the pod from the updated manifest so the kubelet sees the new probe.", IX, PROBE),
    q("k8s-probes", "easy", "A startupProbe exists so that:", "A slow start can fail a few times without the liveness probe restarting the container.", "The pod skips scheduling.", "Readiness is disabled.", "The image is pulled twice.", "Startup runs first. Liveness and readiness take over after it succeeds."),
    q("k8s-resources", "medium", "A pod is Pending and the event says Insufficient cpu. The node looks idle. Why can that happen?", "Scheduling uses requests, not current usage. The requests already claimed the node.", "The scheduler uses live utilization only.", "CPU requests are a limit and cannot cause Pending.", "Insufficient cpu means the image pull failed.", "Lower the request or add a node. Free cycles do not help if they are already promised."),
    q("k8s-resources", "medium", "Guaranteed QoS means:", "Every container has memory and CPU requests equal to limits.", "The pod set a limit and no request.", "The pod set nothing.", "The namespace has a quota.", "Burstable is request without an equal limit. BestEffort is neither. Guaranteed is the one the OOM killer prefers to keep."),
    q("k8s-resources", "hard", "The container is throttled and the node CPU is half idle. What did you set?", "A CPU limit below what the process bursts to. The cgroup enforces the limit even when the node has spare CPU.", "A request with no limit, which always throttles.", "A memory request.", "A liveness probe.", "Limits are ceilings. Requests are the scheduling claim. A low limit on a busy process is a latency bug."),
    q("k8s-resources", "easy", "A memory limit and an OOMKilled status mean:", "The cgroup hit memory.max for that container, or a parent cgroup did. The node may still have memory.", "The cloud bill exceeded the budget.", "The disk is full.", "The probe timed out.", "Raise the limit, find the leak, or stop packing the node until the working set fits."),
    q("k8s-scheduling", "medium", "A node is tainted and your pod has no toleration. What happens?", "The scheduler will not place the pod there.", "The pod runs and is preempted later.", "Taints attract pods.", "The kubelet ignores taints.", "Tolerations let a pod through a taint. They do not by themselves prefer the node. Add affinity or a node selector for that."),
    q("k8s-scheduling", "medium", "You want pods of one app on different nodes. What expresses it?", "A topology spread constraint, or a pod anti-affinity on the hostname.", "A replica count of 1.", "A hostNetwork flag.", "A ClusterIP.", "Spread is a scheduling rule. The Service does not place pods."),
    q("k8s-scheduling", "easy", "nodeSelector does what affinity also does, in the simple case?", "It restricts the pod to nodes with matching labels.", "It sets the request CPU.", "It opens a port.", "It creates a namespace.", "Selector is the small version. Affinity is the one with weights and anti-affinity."),
    q("k8s-scheduling", "hard", "A pod stays Pending with a taint toleration and a node selector that match nothing. Which one is enough to explain it?", "The selector. A toleration does not add a node. It only stops a taint from excluding one.", "The toleration forces a node to appear.", "Pending always means the image is private.", "Selectors are ignored when a toleration is set.", "Read the scheduler events. 'didn't match Pod's node affinity/selector' is the selector. 'had untolerated taint' is the taint."),
    q("k8s-storage", "medium", "A PVC is Pending and the StorageClass exists. What else has to be true for a volume to appear?", "A provisioner for that class is running, and the request's size and mode are something it can satisfy.", "StorageClasses create disks with no provisioner.", "PVCs bind to any PV in the cluster, ignoring size and class.", "Pending means the pod is not using the claim, so the disk exists.", "The claim is an order. Something has to fulfill it, or a matching PV has to already exist."),
    q("k8s-storage", "hard", "A PVC was deleted and the PV is Released, reclaim policy Retain. The data is still on the disk. How do you use it again?", "Clear the PV's claimRef so it can bind to a new claim. Do not expect the old PVC name to come back.", "The Retain policy deletes the disk. That is the Delete policy.", "Released means empty.", "Create a PVC with the same name and the bind is automatic even while claimRef points at the old claim.", "Retain is how you keep the bytes. The bind record is why a new claim sits Pending."),
    q("k8s-storage", "medium", "ReadWriteOnce and two pods on different nodes. What do you get?", "Only one node can mount it. The second pod waits or fails.", "Both mount it. ReadWriteOnce means one namespace.", "The volume becomes ReadWriteMany automatically.", "The claim is cluster-scoped and ignores access modes.", "Use a volume that supports the access, or run the pods where the disk can attach."),
    q("k8s-storage", "easy", "emptyDir lives:", "On the node, for the life of the pod. It is deleted with the pod and is not a persistent disk.", "In the registry.", "In etcd.", "On every node at once.", "Scratch space and caches belong there. A database does not."),
    q("k8s-rbac", "medium", "A user can list pods in one namespace and gets Forbidden in another. The role is a ClusterRole. What is the missing piece?", "A RoleBinding in the other namespace, or a ClusterRoleBinding if you truly want it everywhere.", "A second ClusterRole. ClusterRoles apply to every namespace by existing.", "The pod label.", "A NetworkPolicy.", "A ClusterRole defines permissions. A RoleBinding grants them in one namespace. Existence of the ClusterRole is not a grant."),
    q("k8s-rbac", "hard", "get on nodes/proxy is dangerous because:", "It can be turned into command execution in pods via the kubelet API.", "It only allows reading node CPU, which is why it is in view.", "It is the same as list on configmaps.", "The API server rejects that verb.", "Treat nodes/proxy, pods/exec, and secrets as admin-shaped. Review bindings that grant them.", IX, "https://labs.iximiuz.com/tutorials/nodes-proxy-rce-c9e436a9"),
    q("k8s-rbac", "easy", "A ServiceAccount is:", "The identity a pod runs as. It is not a human user, and binding cluster-admin to the default account is a wide grant.", "Always cluster-admin.", "A Secret type.", "The node user.", "Set automountServiceAccountToken to false when the workload should not talk to the API."),
    q("k8s-rbac", "medium", "kubectl auth can-i is the check you want because:", "It evaluates the combined rules for a user or service account, instead of you reading every binding by hand.", "It edits the role.", "It only works for cluster-admin, so a yes is meaningless.", "It tests NetworkPolicy.", "Ask what the workload can do before you ship the binding."),
    q("k8s-netpol", "medium", "A namespace has no NetworkPolicies. What is the default?", "All pods accept all traffic. A policy changes this only for the pods it selects.", "Default deny.", "Default deny for egress and allow for ingress.", "The CNI blocks everything until you write a policy. Not on a typical Kubernetes install.", "The first policy that selects a pod starts the restriction for that direction. Write the allow you still need, including DNS."),
    q("k8s-netpol", "medium", "You denied all ingress to a backend and the frontend cannot connect. You add an allow from the frontend's pod labels. What else is easy to forget?", "Egress from the frontend, and DNS if you locked that down too. Ingress on the destination is only half of a locked-down pair.", "Nothing. Ingress allow is the whole path.", "A NetworkPolicy opens the cloud security group.", "Policies apply to Services, not pods. They select pods.", "Debug with the direction that is enforced. A default-deny egress needs an allow to the backend and usually to kube-dns."),
    q("k8s-netpol", "hard", "The least permissive policy that still lets frontend talk to backend is:", "One that selects the backend and allows ingress only from the frontend pods, on the backend port, and nothing broader.", "Allow from 0.0.0.0/0 on all ports, which is the smallest YAML.", "A policy with an empty pod selector and an empty ingress list. That is deny, and the frontend would fail.", "A policy in the frontend namespace that cannot select the backend's pods. Namespace matters.", "Empty selectors match everything. Be explicit about namespace and port.", IX, "https://labs.iximiuz.com/challenges/pick-and-deploy-the-least-permissive-network-policy-40a80ba8"),
    q("k8s-netpol", "easy", "NetworkPolicy is enforced by:", "The CNI. If the plugin does not implement it, the objects do nothing.", "The kube-scheduler.", "etcd.", "The Ingress controller only.", "Know whether you are on a CNI that honors policies before you trust the YAML."),
    q("k8s-psa", "medium", "A node agent DaemonSet uses hostNetwork, hostPID, and a hostPath of /proc. The namespace enforces baseline and no pods appear. What level can run that agent?", "privileged. Those host accesses are outside baseline.", "restricted. It is stricter and therefore allows hostPath.", "baseline, if you add a readiness probe.", "No level allows hostPID.", "Do not change the DaemonSet to fit a level it cannot meet. Label the namespace privileged, or exempt it on purpose.", IX, PSA),
    q("k8s-psa", "hard", "The storefront must reject baseline violations and only warn and audit on restricted violations. Which labels?", "enforce=baseline, warn=restricted, audit=restricted.", "enforce=restricted, warn=baseline.", "One label, pod-security=baseline.", "enforce=privileged, because warn implies enforce.", "Each mode is its own label. Audit does not print. It annotates the API audit log.", IX, PSA),
    q("k8s-psa", "medium", "You set enforce=restricted and the existing pods stay Ready, then a rollout creates nothing. Why?", "Enforce applies to new pods. Running pods are left alone until they are replaced, and the new ones are rejected.", "Enforce kills running pods immediately, so this cannot be the symptom.", "Restricted is weaker than baseline.", "The label is only documentation.", "Dry-run the label on the server side before you enforce it, then fix the pod securityContext the rejection names.", IX, PSA),
    q("k8s-psa", "easy", "restricted wants, among other things:", "A non-root user, a seccomp profile, dropped capabilities, and no privilege escalation.", "hostNetwork.", "A privileged container.", "No securityContext at all.", "The payments-style workload has to meet that bar. The monitoring agent will not, and it should not share the namespace policy."),
    q("k8s-helm", "medium", "helm template is the right command when:", "You want the rendered manifests without installing, for review or for another tool to apply.", "You want to upgrade a live release. That is helm upgrade.", "You want to delete a release.", "You want the values schema ignored.", "Template is a render. Install and upgrade talk to the cluster and record a release."),
    q("k8s-helm", "medium", "The chart wants to install CRDs that are already in the cluster and owned elsewhere. What do you skip?", "The chart's CRDs, and install only the namespaced objects.", "The namespace.", "The values file.", "The Deployment, and install only CRDs.", "Re-applying CRDs you do not own is how you fight another controller.", IX, "https://labs.iximiuz.com/challenges/render-argocd-manifests-with-helm-without-reinstalling-existing-crds-cbceeaa3"),
    q("k8s-helm", "easy", "A Helm release is:", "The recorded install of a chart with a name and values, not the chart tarball itself.", "A Docker tag.", "A Namespace.", "A node label.", "Upgrade changes the release. The chart is the package."),
    q("k8s-helm", "hard", "helm upgrade failed halfway and a retry looks confused. What do you look at?", "The release history and whether the last attempt is pending or failed. A stuck pending lock blocks the next upgrade.", "The container runtime only.", "The node's /etc/hosts.", "kubectl get componentstatuses, which explains Helm locks.", "History, status, and the rendered diff. Do not keep retrying a pending release blindly."),
    q("k8s-gitops", "medium", "GitOps means the cluster has a controller that:", "Reads the desired state from git and reconciles the cluster toward it, including undoing a manual hot fix.", "Runs only when a human pushes a button in the cluster.", "Replaces git with etcd as the review tool.", "Deploys whatever is newest in the registry, ignoring git.", "A kubectl edit will be reverted if git is the source of truth. Change git."),
    q("k8s-gitops", "easy", "Flux and Argo CD are both:", "Controllers that reconcile manifests from a repository.", "Container runtimes.", "CNI plugins.", "Secret stores only.", "The model is the same. The objects and the UI differ."),
    q("k8s-gitops", "medium", "A GitOps deploy of a Helm chart should pin:", "The chart version and the values in git, so a reconcile is repeatable.", "latest, so production tracks the chart repo automatically.", "The developer's laptop kubeconfig.", "Nothing. The controller picks the newest digest of every chart on an interval, which is the opposite of the point.", "Unpinned charts are an unreviewed upgrade."),
    q("k8s-gitops", "hard", "The controller cannot commit back to git and it needs an image tag updated. What is a clean pattern?", "A separate automation opens a commit that changes the tag, and the controller only applies what git says.", "Someone kubectl sets the image and the controller is told to ignore that Deployment.", "The controller is given cluster-admin and told to invent tags.", "Image tags cannot be GitOps.", "Git stays the source. CI proposes the tag change. The cluster does not drift ahead of git."),
    q("k8s-hpa", "medium", "An HPA scales on CPU and never adds pods while the process is busy. The target is 50 percent of request, and the request is unset. Why?", "CPU utilization is computed against the request. No request means no percentage.", "HPA uses the limit only.", "CPU metrics ignore requests when they are small.", "The kubelet disables HPA when requests are set. It is the opposite.", "Set the request to what the pod actually needs. The percentage is otherwise meaningless."),
    q("k8s-hpa", "medium", "HPA added pods and they stayed Pending. What limit did you hit?", "The cluster, the quota, or the scheduler. HPA does not create nodes.", "HPA creates nodes itself.", "Pending means the metric server is down, even when the event says insufficient cpu.", "The Service selector.", "Cluster autoscaler or a bigger pool is the next layer. HPA only changes replicas."),
    q("k8s-hpa", "easy", "VPA and HPA differ because:", "VPA changes pod resources. HPA changes the replica count.", "They both only change replicas.", "VPA replaces the scheduler.", "HPA edits Dockerfiles.", "Running both on CPU without care makes them fight. One adds pods, the other changes the request the first one measures."),
    q("k8s-hpa", "hard", "A sidecar and the app share a pod, and VPA should leave the sidecar alone. What is the control?", "A per-container resource policy that excludes the sidecar.", "A second HPA.", "A node taint.", "There is no such split. VPA always rewrites every container.", "The app's recommendation and the sidecar's fixed size are different problems.", IX, "https://labs.iximiuz.com/challenges/exclude-sidecar-from-vpa-using-per-container-resource-policy-82fb0d94"),
    q("k8s-debug", "medium", "CrashLoopBackOff means:", "The process starts and exits, and the kubelet is backing off between restarts.", "The image cannot be pulled. That is ImagePullBackOff.", "The pod is Pending.", "The Service has no endpoints, which may also be true but is not the name of this status.", "Read the previous container logs. The current container may already be dead."),
    q("k8s-debug", "medium", "ImagePullBackOff and a private registry. What is the first check?", "The pull secret, the exact image name, and whether the node can reach the registry.", "The readiness probe.", "The ClusterRole of the default account. That does not pull images.", "The PVC.", "The event text usually says unauthorized, manifest unknown, or a timeout. Those are three different fixes."),
    q("k8s-debug", "hard", "kubectl exec fails because the image has no shell. What do you attach instead?", "kubectl debug with an ephemeral container that shares the process or network namespace.", "A new Deployment in front of the broken one.", "docker exec on your laptop.", "The API server logs, which contain the container filesystem.", "Bring tools in a second container. Do not bake a shell into a distroless image just to debug.", IX, "https://labs.iximiuz.com/skill-paths/master-kubectl-debug"),
    q("k8s-debug", "easy", "kubectl describe is the first stop when a pod is not Running because:", "The events at the bottom say why: pull, schedule, mount, or probe.", "It restarts the pod.", "It prints application logs only.", "It edits the YAML.", "Logs are empty if the process never started. Events still exist."),
    q("k8s-dns", "medium", "A pod cannot resolve a Service name and can resolve the internet. What is the in-cluster path?", "CoreDNS, the cluster search domain, and a NetworkPolicy or kube-proxy path to the DNS service.", "The public resolver is also the cluster resolver, always.", "Service names are in the hosts file of the image.", "Ingress DNS is used for ClusterIP names.", "Check resolv.conf in the pod, then the DNS service endpoints, then policy."),
    q("k8s-dns", "hard", "kubectl suddenly fails with a certificate error and the workloads keep serving. What expired?", "The API server certificate. The data plane does not need a fresh client cert for every request it is already handling.", "The Service ClusterIP.", "Every pod certificate, which would stop traffic.", "The node's SSH host key.", "kubeadm certs check, then renew, then restart the control plane static pods. The running apps can look fine the whole time.", IX, "https://labs.iximiuz.com/challenges/cka-practice-renew-control-plane-certificates-94a449de"),
    q("k8s-dns", "medium", "You need the cluster DNS domain changed from cluster.local. What has to move together?", "CoreDNS and the kubelet configuration on the nodes. Pods learn the search domain from the kubelet.", "Only the Ingress host.", "Only etcd.", "A Service annotation.", "Half of that change leaves resolv.conf and the server disagreeing.", IX, "https://labs.iximiuz.com/challenges/migrate-cluster-dns-domain-cluster-local-to-iximiuz-cluster-467d9f1c"),
    q("k8s-dns", "easy", "A Service named web in namespace shop is reached from another namespace as:", "web.shop.svc.cluster.local, or a shorter name if the search path supplies the rest.", "web, from every namespace, with no suffix, always.", "The node hostname.", "The ingress class name.", "Short names depend on the caller's search list. The fully qualified name does not."),
]
